import { ButtonProps, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import { useCopyToClipboard } from "@/core/hooks";

type Props = {
  /** The text that is written to the clipboard when the button is clicked */
  textToCopy: string;
  /** Button label in the idle state, before anything has been copied */
  copyLabel: string;
  /** Label shown for the three seconds after a copy, instead of the `copied` translation */
  copiedDoneLabelOverride?: string;
} & Omit<ButtonProps, "label" | "iconRightNew" | "onClick">;

export const CopyClipboardButton = ({ textToCopy, copyLabel, copiedDoneLabelOverride, ...rest }: Props) => {
  const { t } = useTranslation();

  const { copied, copyToClipboard } = useCopyToClipboard(textToCopy);

  const copiedDoneLabel = copiedDoneLabelOverride || t("copied");

  return (
    <PrimaryButton
      onClick={copyToClipboard}
      label={copied ? copiedDoneLabel : copyLabel}
      iconRightNew={copied ? "done" : "copy"}
      {...rest}
    />
  );
};
