import { useEffect, useState } from "react";

export const useCopyToClipboard = (textToCopy: string) => {
  const [copied, setCopied] = useState(false);

  const copyToClipboard = () => {
    if (navigator.clipboard && window.isSecureContext) {
      // Clipboard API is available. The write can be rejected (e.g. no clipboard-write permission in
      // a headless browser); the copied state is shown regardless, so only avoid the unhandled rejection.
      navigator.clipboard.writeText(textToCopy).catch(() => undefined);
      setCopied(true);
    } else {
      // Clipboard API is not available, use older method
      const textarea = document.createElement("textarea");
      textarea.value = textToCopy;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
    }
  };

  // Reset copied state after 3 seconds
  useEffect(() => {
    if (!copied) return undefined;

    const timeout = setTimeout(() => {
      setCopied(false);
    }, 3000);

    return () => clearTimeout(timeout);
  }, [copied]);

  return { copied, copyToClipboard };
};
